import{_ as o,o as s,c as t,a0 as r}from"./chunks/framework.B27pdwYF.js";const h=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/concepts.md","filePath":"explanation/concepts.md"}'),a={name:"explanation/concepts.md"};function c(d,e,i,n,l,p){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>lasius&#39;s vocabulary is about <em>the workspace as a unit</em> — one root directory that owns every clone of an org.</p><h2 id="workspace-entities" tabindex="-1">Workspace entities <a class="header-anchor" href="#workspace-entities" aria-label="Permalink to &quot;Workspace entities&quot;">​</a></h2><ul><li><strong>Workspace root</strong> — the directory containing <code>lasius.toml</code>; everything lasius manages hangs off it. The workspace repo itself is a normal git repo tracking config and docs only.</li><li><strong><code>repos_dir</code></strong> — where clones live (<code>repos/</code> by default, gitignored). Independent clones — no submodules, each keeps its own history and remotes.</li><li><strong>Clone</strong> — a local checkout of one org repo under <code>repos_dir</code>. <code>status</code>/<code>update</code>/<code>code-workspace generate</code> iterate <em>local clones</em>, not the provider&#39;s repo list — a manually added clone is managed too.</li><li><strong>Provider</strong> — how org repos are discovered (<code>provider = &quot;github&quot;</code> → <code>gh repo list --json</code>). Archived repos are excluded; private ones opt in.</li><li><strong><code>lasius.toml</code></strong> — the whole config: <code>org</code>, <code>repos_dir</code>, <code>workspace_file</code>, <code>provider</code>, <code>exclude</code> globs, <code>include_private</code>.</li><li><strong>Workspace file</strong> — the generated <code>*.code-workspace</code> multi-root file editors open; gitignored, regenerated on demand.</li></ul><h2 id="filters-and-safety" tabindex="-1">Filters and safety <a class="header-anchor" href="#filters-and-safety" aria-label="Permalink to &quot;Filters and safety&quot;">​</a></h2><ul><li><strong><code>exclude</code></strong> — glob patterns matched against repo names; matched repos are never cloned.</li><li><strong><code>include_private</code></strong> — opt-in flag; private repos join discovery (requires authenticated <code>gh</code>).</li><li><strong>Safety checks</strong> — <code>rm</code> refuses dirty trees, unpushed commits, stashes, linked worktrees, nested <code>.git</code> dirs, and extra remotes unless <code>--force</code>. Repo names from <code>gh</code> are validated before they become path segments.</li></ul><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><ul><li><strong><code>lasius-vcs</code></strong> — VCS port (history/worktree/tag/sync + agent-mutation ops) shared by tarsi/mimus/bupha/kuda/sturn consumers (P-019); <code>lasius-vcs-git</code> shells out to <code>git</code>.</li><li><strong><code>lasius-forge</code></strong> — forge port (PRs, merges, checks, commit statuses); <code>lasius-forge-gh</code> shells out to <code>gh</code>.</li></ul><h2 id="surfaces" tabindex="-1">Surfaces <a class="header-anchor" href="#surfaces" aria-label="Permalink to &quot;Surfaces&quot;">​</a></h2><p><code>lasius</code> CLI for humans and scripts; <code>lasius serve</code> speaks ndjson JSON-RPC read-only ops (<code>ping</code>, <code>list</code>, <code>status</code>, <code>doctor</code>) for embedding — the org wire convention shared with tamias, sepia, cuora, and myco; <code>lasius-driver</code> exposes the same ops to pavo.</p>',10)])])}const g=o(a,[["render",c]]);export{h as __pageData,g as default};
